class Solution:
    def waysToPaint(self, n: int, limit: List[int]) -> int:
        MOD = 10**9 + 7
        m = len(limit)
        a = [min(x, n - 1) for x in limit]
        b = sorted(max(1, n - x) for x in limit)
        pre = [0]
        for x in b:
            pre.append(pre[-1] + x)
        import bisect
        total = 0
        for ai in a:
            k = bisect.bisect_right(b, ai)
            total += k * (ai + 1) - pre[k]
        for x, y in zip(a, [max(1, n - v) for v in limit]):
            if ai_diag := (x - y + 1):
                if ai_diag > 0:
                    total -= ai_diag
        return total % MOD

