class Solution {
public:
    int waysToPaint(int n, vector<int>& limit) {
        const long long MOD = 1e9 + 7;
        int m = limit.size();
        vector<long long> a(m), b(m);
        for (int i = 0; i < m; i++) {
            a[i] = min((long long)limit[i], (long long)n - 1);
            b[i] = max(1LL, (long long)n - limit[i]);
        }
        vector<long long> bs = b;
        sort(bs.begin(), bs.end());
        vector<long long> pre(m + 1, 0);
        for (int i = 0; i < m; i++) pre[i+1] = pre[i] + bs[i];
        long long total = 0;
        for (long long ai : a) {
            int k = upper_bound(bs.begin(), bs.end(), ai) - bs.begin();
            total += k * (ai + 1) - pre[k];
        }
        for (int i = 0; i < m; i++)
            total -= max(0LL, a[i] - b[i] + 1);
        return (int)(total % MOD);
    }
};

