class Solution {
    public int waysToPaint(int n, int[] limit) {
        final long MOD = 1_000_000_007L;
        int m = limit.length;
        long[] a = new long[m], b = new long[m];
        for (int i = 0; i < m; i++) {
            a[i] = Math.min(limit[i], n - 1);
            b[i] = Math.max(1, n - limit[i]);
        }
        long[] bs = b.clone();
        java.util.Arrays.sort(bs);
        long[] pre = new long[m + 1];
        for (int i = 0; i < m; i++) pre[i+1] = pre[i] + bs[i];
        long total = 0;
        for (long ai : a) {
            int k = java.util.Arrays.binarySearch(bs, ai);
            if (k < 0) k = -(k + 1);
            else { k++; while (k < m && bs[k] == ai) k++; }
            total += k * (ai + 1) - pre[k];
        }
        for (int i = 0; i < m; i++)
            total -= Math.max(0, a[i] - b[i] + 1);
        return (int)(total % MOD);
    }
}

