var waysToPaint = function(n, limit) {
    const MOD = 1e9 + 7, m = limit.length;
    const a = limit.map(x => Math.min(x, n - 1));
    const bRaw = limit.map(x => Math.max(1, n - x));
    const b = [...bRaw].sort((x, y) => x - y);
    const pre = [0];
    for (const x of b) pre.push(pre[pre.length - 1] + x);
    let total = 0;
    for (const ai of a) {
        let lo = 0, hi = m;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (b[mid] <= ai) lo = mid + 1; else hi = mid; }
        total += lo * (ai + 1) - pre[lo];
    }
    for (let i = 0; i < m; i++)
        total -= Math.max(0, a[i] - bRaw[i] + 1);
    return ((total % MOD) + MOD) % MOD;
};

